UPDATE public.site_settings SET seo_title=replace(seo_title,'2011','2026'), seo_description=replace(seo_description,'2011','2026'), seo_keywords=replace(seo_keywords,'2011','2026'), company_name=replace(company_name,'2011','2026'), address=replace(address,'2011','2026');
UPDATE public.products SET intro_en=replace(intro_en,'2011','2026'), intro_ar=replace(intro_ar,'2011','2026'), description_en=replace(description_en,'2011','2026'), description_ar=replace(description_ar,'2011','2026'), specs_en=replace(specs_en::text,'2011','2026')::jsonb, specs_ar=replace(specs_ar::text,'2011','2026')::jsonb;
UPDATE public.news SET title=replace(title,'2011','2026'), title_ar=replace(title_ar,'2011','2026'), excerpt=replace(excerpt,'2011','2026'), excerpt_ar=replace(excerpt_ar,'2011','2026'), content=replace(content,'2011','2026'), content_ar=replace(content_ar,'2011','2026');